Here's a possible implementation in Java:

```java
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CarCounter {

    public static class CarColorCount {
        private int count;
        private String color;

        public CarColorCount(int count, String color) {
            this.count = count;
            this.color = color;
        }

        public int getCount() {
            return count;
        }

        public String getColor() {
            return color;
        }
    }

    public static CarColorCount getMostPopularColor(List<Car> cars) {
        if (cars == null || cars.isEmpty()) {
            return new CarColorCount(0, null);
        }

        HashMap<String, Integer> colorCountMap = new HashMap<>();

        for (Car car : cars) {
            String color = car.getColor();
            colorCountMap.put(color, colorCountMap.getOrDefault(color, 0) + 1);
        }

        String mostPopularColor = null;
        int maxCount = 0;

        for (Map.Entry<String, Integer> entry : colorCountMap.entrySet()) {
            if (entry.getValue() > maxCount) {
                mostPopularColor = entry.getKey();
                maxCount = entry.getValue();
            }
        }

        return new CarColorCount(maxCount, mostPopularColor);
    }
}
```

